/**
 * Single source of truth for every piece of business content on the site.
 * Components must never hardcode text, prices, hours or links — import from here.
 *
 * NOTE: "Ember & Oak" is a FICTIONAL restaurant. This site is a portfolio
 * concept demo and is labelled as such in the footer.
 */

import { getGeneralWhatsAppUrl } from "@/lib/whatsapp";

export interface Dish {
  name: string;
  slug: string;
  desc: string;
  price: number;
  veg?: boolean;
  image: string;
  alt: string;
}

export interface SignatureDish extends Dish {
  wideImage?: string;
}

export interface MenuCategory {
  id: string;
  label: string;
  dishes: Dish[];
}

export interface Testimonial {
  quote: string;
  author: string;
  source: string;
}

export interface PrivateRoom {
  name: string;
  capacity: string;
  minSpend: string;
}

export interface SetMenu {
  name: string;
  price: string;
  note: string;
}

export interface HoursEntry {
  days: string;
  time: string;
}

export interface NavLink {
  href: string;
  label: string;
}

export interface SelectOption {
  value: string;
  label: string;
}

