"use client";

import { useCallback, useEffect, useId, useRef, useState } from "react";
import MenuRow from "@/components/ui/MenuRow";
import site from "@/content/site";

export function getValidCategoryId(raw?: string | null): string | null {
  if (!raw) return null;
  const cleaned = raw.trim().toLowerCase().replace(/^#/, "");
  const found = site.menu.find(
    (cat) => cat.id.toLowerCase() === cleaned || cat.label.toLowerCase() === cleaned,
  );
  return found ? found.id : null;
}

interface MenuTabsProps {
  initialCategory?: string;
}

/**
 * Client-side category switcher. Tabs follow the ARIA tabs pattern with
 * roving focus; the active tab is marked by an ink underline.
 */
export default function MenuTabs({ initialCategory }: MenuTabsProps = {}) {
  const defaultCategory =
    getValidCategoryId(initialCategory) ?? site.menu[0].id;
  const [active, setActive] = useState(defaultCategory);
  const baseId = useId();
  const tablistRef = useRef<HTMLDivElement>(null);

  const scrollTabIntoView = useCallback(
    (tabId: string, behavior: ScrollBehavior = "smooth") => {
      const container = tablistRef.current;
      if (!container) return;
      const tab = document.getElementById(`${baseId}-tab-${tabId}`);
      if (!tab) return;

      const containerRect = container.getBoundingClientRect();
      const tabRect = tab.getBoundingClientRect();
      const style = window.getComputedStyle(container);
      const paddingLeft = parseFloat(style.paddingLeft) || 0;
      const paddingRight = parseFloat(style.paddingRight) || 0;

      const prefersReducedMotion = window.matchMedia(
        "(prefers-reduced-motion: reduce)",
      ).matches;
      const effectiveBehavior = prefersReducedMotion ? "auto" : behavior;

      if (tabRect.right > containerRect.right - paddingRight) {
        const diff = tabRect.right - (containerRect.right - paddingRight);
        container.scrollTo({
          left: container.scrollLeft + diff,
          behavior: effectiveBehavior,
        });
      } else if (tabRect.left < containerRect.left + paddingLeft) {
        const diff = containerRect.left + paddingLeft - tabRect.left;
        container.scrollTo({
          left: container.scrollLeft - diff,
          behavior: effectiveBehavior,
        });
      }
    },
    [baseId],
  );

  function updateUrl(categoryId: string, method: "push" | "replace" = "push") {
    if (typeof window === "undefined") return;
    const url = new URL(window.location.href);
    url.searchParams.set("category", categoryId);
    url.searchParams.delete("tab");
    if (url.hash) {
      url.hash = "";
    }
    const newUrl = url.pathname + (url.search ? url.search : "");
    if (window.location.pathname + window.location.search !== newUrl) {
      if (method === "push") {
        window.history.pushState({ category: categoryId }, "", newUrl);
      } else {
        window.history.replaceState({ category: categoryId }, "", newUrl);
      }
    }
  }

  function selectCategory(
    id: string,
    method: "push" | "replace" = "push",
    behavior: ScrollBehavior = "smooth",
  ) {
    if (id !== active) {
      setActive(id);
      updateUrl(id, method);
    }
    scrollTabIntoView(id, behavior);
  }

  function activateTab(index: number) {
    const next = site.menu[(index + site.menu.length) % site.menu.length];
    selectCategory(next.id, "replace", "smooth");
    document.getElementById(`${baseId}-tab-${next.id}`)?.focus({ preventScroll: true });
  }

  function onKeyDown(event: React.KeyboardEvent<HTMLButtonElement>, index: number) {
    let nextIndex: number | null = null;

    if (event.key === "ArrowRight") nextIndex = index + 1;
    if (event.key === "ArrowLeft") nextIndex = index - 1;
    if (event.key === "Home") nextIndex = 0;
    if (event.key === "End") nextIndex = site.menu.length - 1;
    if (nextIndex === null) return;

    event.preventDefault();
    activateTab(nextIndex);
  }

  // Handle browser Back / Forward (popstate) and hash changes
  useEffect(() => {
    function handleLocationChange() {
      const params = new URLSearchParams(window.location.search);
      const catParam =
        params.get("category") ||
        params.get("tab") ||
        window.location.hash.replace("#", "");
      const validId = getValidCategoryId(catParam) ?? site.menu[0].id;
      setActive(validId);
      requestAnimationFrame(() => {
        scrollTabIntoView(validId, "auto");
      });
    }

    window.addEventListener("popstate", handleLocationChange);
    window.addEventListener("hashchange", handleLocationChange);
    return () => {
      window.removeEventListener("popstate", handleLocationChange);
      window.removeEventListener("hashchange", handleLocationChange);
    };
  }, [scrollTabIntoView]);

  // On mount: check initial hash and scroll active tab into view
  useEffect(() => {
    const hash = window.location.hash.replace("#", "");
    const hashId = getValidCategoryId(hash);
    if (hashId && hashId !== defaultCategory) {
      requestAnimationFrame(() => {
        setActive(hashId);
        scrollTabIntoView(hashId, "auto");
      });
    } else {
      requestAnimationFrame(() => {
        scrollTabIntoView(defaultCategory, "auto");
      });
    }
  }, [defaultCategory, scrollTabIntoView]);

  // Keep selected tab visible on window resize
  useEffect(() => {
    function handleResize() {
      scrollTabIntoView(active, "auto");
    }
    window.addEventListener("resize", handleResize);
    return () => window.removeEventListener("resize", handleResize);
  }, [active, scrollTabIntoView]);

  return (
    <div>
      {/* Tabs scroll horizontally on narrow screens rather than wrapping. */}
      <div
        ref={tablistRef}
        role="tablist"
        aria-label="Menu categories"
        className="-mx-5 flex gap-7 overflow-x-auto border-b px-5 sm:mx-0 sm:px-0"
      >
        {site.menu.map((category, index) => {
          const selected = category.id === active;

          return (
            <button
              key={category.id}
              id={`${baseId}-tab-${category.id}`}
              role="tab"
              type="button"
              aria-selected={selected}
              aria-controls={`${baseId}-panel-${category.id}`}
              tabIndex={selected ? 0 : -1}
              onClick={() => selectCategory(category.id, "push", "smooth")}
              onKeyDown={(event) => onKeyDown(event, index)}
              className={`label-caps -mb-px min-h-11 shrink-0 border-b-2 py-4 transition-colors duration-300 ${
                selected
                  ? "border-ink text-ink"
                  : "border-transparent text-muted hover:text-ink"
              }`}
            >
              {category.label}
            </button>
          );
        })}
      </div>

      {site.menu.map((category) => {
        const selected = category.id === active;

        return (
          <div
            key={category.id}
            id={`${baseId}-panel-${category.id}`}
            role="tabpanel"
            aria-labelledby={`${baseId}-tab-${category.id}`}
            tabIndex={selected ? 0 : -1}
            hidden={!selected}
            className="focus-visible:outline-none"
          >
            <h2 className="sr-only">{category.label}</h2>
            <ul className="mt-2">
              {category.dishes.map((dish) => (
                <MenuRow key={dish.slug} dish={dish} />
              ))}
            </ul>
          </div>
        );
      })}
    </div>
  );
}

