  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const catParam =
      params.get("category") ||
      params.get("tab") ||
      window.location.hash.replace("#", "");
    const targetId = getValidCategoryId(catParam) ?? active;
    if (targetId !== active) {
      setActive(targetId);
    }
    requestAnimationFrame(() => {
      scrollTabIntoView(targetId, "auto");
    });
  }, []);

  // Sync if initialCategory prop changes (e.g. server navigation)
  useEffect(() => {
    if (initialCategory) {
      const valid = getValidCategoryId(initialCategory);
      if (valid && valid !== active) {
        setActive(valid);
        requestAnimationFrame(() => {
          scrollTabIntoView(valid, "auto");
        });
      }
    }
  }, [initialCategory]);

  // Keep selected tab visible on window resize
  useEffect(() => {
    function handleResize() {
      scrollTabIntoView(active, "auto");
    }
    window.addEventListener("resize", handleResize);
    return () => window.removeEventListener("resize", handleResize);
  }, [active, baseId]);

