import http from "node:http";
import fs from "node:fs";

async function cdpRequest(endpoint) {
  return new Promise((resolve, reject) => {
    http.get(`http://localhost:9222${endpoint}`, (res) => {
      let data = "";
      res.on("data", (chunk) => (data += chunk));
      res.on("end", () => resolve(JSON.parse(data)));
    }).on("error", reject);
  });
}

class CDPClient {
  constructor(wsUrl) {
    this.ws = new WebSocket(wsUrl);
    this.id = 1;
    this.callbacks = new Map();
    this.events = new Map();

    this.ws.onmessage = (event) => {
      const msg = JSON.parse(event.data);
      if (msg.id && this.callbacks.has(msg.id)) {
        const { resolve, reject } = this.callbacks.get(msg.id);
        this.callbacks.delete(msg.id);
        if (msg.error) reject(msg.error);
        else resolve(msg.result);
      }
      if (msg.method) {
        const handler = this.events.get(msg.method);
        if (handler) handler(msg.params);
      }
    };
  }

  async ready() {
    if (this.ws.readyState === WebSocket.OPEN) return;
    return new Promise((resolve) => {
      this.ws.onopen = () => resolve();
    });
  }

  send(method, params = {}) {
    return new Promise((resolve, reject) => {
      const id = this.id++;
      this.callbacks.set(id, { resolve, reject });
      this.ws.send(JSON.stringify({ id, method, params }));
    });
  }

  async eval(expr) {
    const res = await this.send("Runtime.evaluate", {
      expression: expr,
      returnByValue: true,
      awaitPromise: true,
    });
    if (res.exceptionDetails) {
      throw new Error(JSON.stringify(res.exceptionDetails));
    }
    return res.result.value;
  }

  async screenshot(filePath) {
    const res = await this.send("Page.captureScreenshot", { format: "png" });
    fs.writeFileSync(filePath, Buffer.from(res.data, "base64"));
  }
}

async function run() {
  const newTarget = await cdpRequest("/json/new?about:blank");
  console.log("New page target:", newTarget.id);

  const client = new CDPClient(newTarget.webSocketDebuggerUrl);
  await client.ready();
  await client.send("Page.enable");
  await client.send("DOM.enable");

  // Helper to set viewport
  async function setViewport(width, height) {
    await client.send("Emulation.setDeviceMetricsOverride", {
      width,
      height,
      deviceScaleFactor: 2,
      mobile: width < 600,
    });
  }

  // Helper to wait
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

  console.log("=== TEST 1: 320px phone width ===");
  await setViewport(320, 600);
  await client.send("Page.navigate", { url: "http://localhost:3000/menu" });
  await sleep(1500);

  let initialActive = await client.eval(`
    (() => {
      const activeBtn = document.querySelector('[role="tab"][aria-selected="true"]');
      const tabs = Array.from(document.querySelectorAll('[role="tab"]')).map(t => ({
        id: t.id,
        text: t.innerText.trim(),
        selected: t.getAttribute('aria-selected'),
        rect: t.getBoundingClientRect()
      }));
      const container = document.querySelector('[role="tablist"]');
      return {
        activeText: activeBtn?.innerText.trim(),
        containerRect: container?.getBoundingClientRect(),
        scrollLeft: container?.scrollLeft,
        scrollWidth: container?.scrollWidth,
        clientWidth: container?.clientWidth,
        tabs
      };
    })()
  `);
  console.log("Initial state at 320px:", JSON.stringify(initialActive, null, 2));

  console.log("Clicking 'Drinks' tab at 320px...");
  await client.eval(`
    (() => {
      const drinksBtn = Array.from(document.querySelectorAll('[role="tab"]')).find(t => t.innerText.includes('DRINKS'));
      drinksBtn.click();
    })()
  `);
  await sleep(600);

  let afterClickDrinks = await client.eval(`
    (() => {
      const activeBtn = document.querySelector('[role="tab"][aria-selected="true"]');
      const container = document.querySelector('[role="tablist"]');
      const containerRect = container.getBoundingClientRect();
      const tabRect = activeBtn.getBoundingClientRect();
      return {
        activeText: activeBtn?.innerText.trim(),
        containerScrollLeft: container.scrollLeft,
        containerRect: { left: containerRect.left, right: containerRect.right, width: containerRect.width },
        tabRect: { left: tabRect.left, right: tabRect.right, width: tabRect.width },
        isFullyVisible: tabRect.left >= containerRect.left && tabRect.right <= containerRect.right,
        url: window.location.href
      };
    })()
  `);
  console.log("After clicking Drinks at 320px:", JSON.stringify(afterClickDrinks, null, 2));
  await client.screenshot("/tmp/test_320px_drinks_selected.png");

  console.log("=== TEST 2: Keyboard Navigation at 320px ===");
  // Press ArrowLeft
  console.log("Pressing ArrowLeft (should go to Desserts)...");
  await client.eval(`
    (() => {
      const activeBtn = document.querySelector('[role="tab"][aria-selected="true"]');
      activeBtn.dispatchEvent(new KeyboardEvent('keydown', { key: 'ArrowLeft', bubbles: true }));
    })()
  `);
  await sleep(400);

  let afterArrowLeft = await client.eval(`
    (() => {
      const activeBtn = document.querySelector('[role="tab"][aria-selected="true"]');
      const container = document.querySelector('[role="tablist"]');
      const cRect = container.getBoundingClientRect();
      const tRect = activeBtn.getBoundingClientRect();
      return {
        activeText: activeBtn.innerText.trim(),
        url: window.location.href,
        isFullyVisible: tRect.left >= cRect.left && tRect.right <= cRect.right
      };
    })()
  `);
  console.log("After ArrowLeft:", afterArrowLeft);

  // Press Home (should go to Starters)
  console.log("Pressing Home (should go to Starters)...");
  await client.eval(`
    (() => {
      const activeBtn = document.querySelector('[role="tab"][aria-selected="true"]');
      activeBtn.dispatchEvent(new KeyboardEvent('keydown', { key: 'Home', bubbles: true }));
    })()
  `);
  await sleep(400);

  let afterHome = await client.eval(`
    (() => {
      const activeBtn = document.querySelector('[role="tab"][aria-selected="true"]');
      const container = document.querySelector('[role="tablist"]');
      const cRect = container.getBoundingClientRect();
      const tRect = activeBtn.getBoundingClientRect();
      return {
        activeText: activeBtn.innerText.trim(),
        url: window.location.href,
        isFullyVisible: tRect.left >= cRect.left && tRect.right <= cRect.right
      };
    })()
  `);
  console.log("After Home:", afterHome);

  // Press End (should go to Drinks)
  console.log("Pressing End (should go to Drinks)...");
  await client.eval(`
    (() => {
      const activeBtn = document.querySelector('[role="tab"][aria-selected="true"]');
      activeBtn.dispatchEvent(new KeyboardEvent('keydown', { key: 'End', bubbles: true }));
    })()
  `);
  await sleep(400);

  let afterEnd = await client.eval(`
    (() => {
      const activeBtn = document.querySelector('[role="tab"][aria-selected="true"]');
      const container = document.querySelector('[role="tablist"]');
      const cRect = container.getBoundingClientRect();
      const tRect = activeBtn.getBoundingClientRect();
      return {
        activeText: activeBtn.innerText.trim(),
        url: window.location.href,
        isFullyVisible: tRect.left >= cRect.left && tRect.right <= cRect.right
      };
    })()
  `);
  console.log("After End:", afterEnd);

  console.log("=== TEST 3: Navigation & Back Button Flow at 390px ===");
  await setViewport(390, 844);
  await client.send("Page.navigate", { url: "http://localhost:3000/menu" });
  await sleep(1500);

  console.log("Selecting Desserts tab...");
  await client.eval(`
    (() => {
      const btn = Array.from(document.querySelectorAll('[role="tab"]')).find(t => t.innerText.includes('DESSERTS'));
      btn.click();
    })()
  `);
  await sleep(400);

  await client.screenshot("/tmp/test_390px_desserts_selected.png");

  console.log("Clicking 'Reserve a table' on Burnt Basque Cheesecake...");
  await client.eval(`
    (() => {
      const reserveLink = Array.from(document.querySelectorAll('a')).find(a => a.href.includes('Burnt') || a.getAttribute('aria-label')?.includes('Burnt'));
      reserveLink.click();
    })()
  `);
  await sleep(1500);

  let reservePageUrl = await client.eval(`window.location.href`);
  console.log("On Reserve page, URL:", reservePageUrl);
  await client.screenshot("/tmp/test_390px_reserve_page.png");

  console.log("Pressing browser Back button...");
  await client.eval(`window.history.back()`);
  await sleep(1500);

  let backResult = await client.eval(`
    (() => {
      const activeBtn = document.querySelector('[role="tab"][aria-selected="true"]');
      const activePanel = document.querySelector('[role="tabpanel"]:not([hidden])');
      return {
        url: window.location.href,
        activeTab: activeBtn?.innerText.trim(),
        panelHeading: activePanel?.querySelector('h2')?.innerText.trim(),
        firstDish: activePanel?.querySelector('h3')?.innerText.trim()
      };
    })()
  `);
  console.log("After Back button on Menu page:", JSON.stringify(backResult, null, 2));
  await client.screenshot("/tmp/test_390px_after_back.png");

  console.log("=== TEST 4: Direct URL links ===");
  console.log("Navigating directly to /menu?category=desserts...");
  await client.send("Page.navigate", { url: "http://localhost:3000/menu?category=desserts" });
  await sleep(1500);
  let directDesserts = await client.eval(`
    (() => {
      const activeBtn = document.querySelector('[role="tab"][aria-selected="true"]');
      const activePanel = document.querySelector('[role="tabpanel"]:not([hidden])');
      return {
        url: window.location.href,
        activeTab: activeBtn?.innerText.trim(),
        firstDish: activePanel?.querySelector('h3')?.innerText.trim()
      };
    })()
  `);
  console.log("Direct link /menu?category=desserts:", directDesserts);

  console.log("Navigating directly to /menu?category=drinks at 320px...");
  await setViewport(320, 600);
  await client.send("Page.navigate", { url: "http://localhost:3000/menu?category=drinks" });
  await sleep(1500);
  let directDrinks320 = await client.eval(`
    (() => {
      const activeBtn = document.querySelector('[role="tab"][aria-selected="true"]');
      const container = document.querySelector('[role="tablist"]');
      const cRect = container.getBoundingClientRect();
      const tRect = activeBtn.getBoundingClientRect();
      return {
        url: window.location.href,
        activeTab: activeBtn?.innerText.trim(),
        isFullyVisible: tRect.left >= cRect.left && tRect.right <= cRect.right,
        tabRect: { left: tRect.left, right: tRect.right },
        containerRect: { left: cRect.left, right: cRect.right }
      };
    })()
  `);
  console.log("Direct link /menu?category=drinks at 320px:", directDrinks320);

  console.log("=== TEST 5: Desktop 1280px width ===");
  await setViewport(1280, 800);
  await client.send("Page.navigate", { url: "http://localhost:3000/menu" });
  await sleep(1500);
  await client.screenshot("/tmp/test_desktop_initial.png");

  console.log("All tests completed!");
  process.exit(0);
}

run().catch((e) => {
  console.error("Test error:", e);
  process.exit(1);
});

