import http from "node:http";

async function cdpRequest(endpoint, method = "GET") {
  return new Promise((resolve, reject) => {
    const req = http.request(`http://localhost:9222${endpoint}`, { method }, (res) => {
      let data = "";
      res.on("data", (chunk) => (data += chunk));
      res.on("end", () => resolve(JSON.parse(data)));
    });
    req.on("error", reject);
    req.end();
  });
}

class CDPClient {
  constructor(wsUrl) {
    this.ws = new WebSocket(wsUrl);
    this.id = 1;
    this.callbacks = new Map();

    this.ws.onmessage = (event) => {
      const msg = JSON.parse(event.data);
      if (msg.id && this.callbacks.has(msg.id)) {
        const { resolve, reject } = this.callbacks.get(msg.id);
        this.callbacks.delete(msg.id);
        if (msg.error) reject(msg.error);
        else resolve(msg.result);
      }
    };
  }

  async ready() {
    if (this.ws.readyState === WebSocket.OPEN) return;
    return new Promise((resolve) => {
      this.ws.onopen = () => resolve();
    });
  }

  send(method, params = {}) {
    return new Promise((resolve, reject) => {
      const id = this.id++;
      this.callbacks.set(id, { resolve, reject });
      this.ws.send(JSON.stringify({ id, method, params }));
    });
  }

  async eval(expr) {
    const res = await this.send("Runtime.evaluate", {
      expression: expr,
      returnByValue: true,
      awaitPromise: true,
    });
    if (res.exceptionDetails) {
      throw new Error(JSON.stringify(res.exceptionDetails));
    }
    return res.result.value;
  }
}

async function run() {
  const target = await cdpRequest("/json/new?about:blank", "PUT");
  const client = new CDPClient(target.webSocketDebuggerUrl);
  await client.ready();
  await client.send("Page.enable");

  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

  async function waitForSelector(selector) {
    for (let i = 0; i < 50; i++) {
      const ok = await client.eval(`Boolean(document.querySelector('${selector}'))`);
      if (ok) return;
      await sleep(100);
    }
    throw new Error(`Timeout waiting for ${selector}`);
  }

  // Set viewport to 320px
  await client.send("Emulation.setDeviceMetricsOverride", {
    width: 320,
    height: 600,
    deviceScaleFactor: 2,
    mobile: true,
  });

  await client.send("Page.navigate", { url: "http://localhost:3000/menu" });
  await waitForSelector('[role="tab"]');
  await sleep(500);

  async function checkState() {
    return await client.eval(`
      (() => {
        const activeTab = document.querySelector('[role="tab"][aria-selected="true"]');
        const activePanel = document.querySelector('[role="tabpanel"]:not([hidden])');
        const focused = document.activeElement;
        const container = document.querySelector('[role="tablist"]');
        const cRect = container.getBoundingClientRect();
        const tRect = activeTab.getBoundingClientRect();
        return {
          activeTabText: activeTab?.innerText.trim(),
          focusedTabText: focused?.innerText?.trim(),
          isFocusMatching: activeTab === focused,
          panelTitle: activePanel?.querySelector('h2')?.innerText.trim(),
          url: window.location.href,
          isFullyVisible: tRect.left >= cRect.left && tRect.right <= cRect.right,
          tabRect: { left: Math.round(tRect.left), right: Math.round(tRect.right) },
          containerRect: { left: Math.round(cRect.left), right: Math.round(cRect.right) }
        };
      })()
    `);
  }

  console.log("Initial state:", await checkState());

  // Focus the first tab
  await client.eval(`document.querySelector('[role="tab"][aria-selected="true"]').focus()`);

  // ArrowRight -> Mains
  console.log("\nPressing ArrowRight (expect Mains)...");
  await client.eval(`document.activeElement.dispatchEvent(new KeyboardEvent('keydown', { key: 'ArrowRight', bubbles: true }))`);
  await sleep(300);
  console.log("State:", await checkState());

  // ArrowRight -> Desserts
  console.log("\nPressing ArrowRight (expect Desserts)...");
  await client.eval(`document.activeElement.dispatchEvent(new KeyboardEvent('keydown', { key: 'ArrowRight', bubbles: true }))`);
  await sleep(300);
  console.log("State:", await checkState());

  // ArrowRight -> Drinks
  console.log("\nPressing ArrowRight (expect Drinks)...");
  await client.eval(`document.activeElement.dispatchEvent(new KeyboardEvent('keydown', { key: 'ArrowRight', bubbles: true }))`);
  await sleep(300);
  console.log("State:", await checkState());

  // ArrowRight -> Wraps to Starters
  console.log("\nPressing ArrowRight (expect wrap to Starters)...");
  await client.eval(`document.activeElement.dispatchEvent(new KeyboardEvent('keydown', { key: 'ArrowRight', bubbles: true }))`);
  await sleep(300);
  console.log("State:", await checkState());

  // ArrowLeft -> Wraps to Drinks
  console.log("\nPressing ArrowLeft (expect wrap to Drinks)...");
  await client.eval(`document.activeElement.dispatchEvent(new KeyboardEvent('keydown', { key: 'ArrowLeft', bubbles: true }))`);
  await sleep(300);
  console.log("State:", await checkState());

  // End -> Drinks
  console.log("\nPressing End (expect Drinks)...");
  await client.eval(`document.activeElement.dispatchEvent(new KeyboardEvent('keydown', { key: 'End', bubbles: true }))`);
  await sleep(300);
  console.log("State:", await checkState());

  // Home -> Starters
  console.log("\nPressing Home (expect Starters)...");
  await client.eval(`document.activeElement.dispatchEvent(new KeyboardEvent('keydown', { key: 'Home', bubbles: true }))`);
  await sleep(300);
  console.log("State:", await checkState());

  console.log("\nTesting Hash navigation: changing hash to #desserts...");
  await client.eval(`window.location.hash = 'desserts'`);
  await sleep(300);
  console.log("State after hashchange:", await checkState());

  console.log("\nAll keyboard and ARIA tests verified successfully!");
  process.exit(0);
}

run().catch((e) => {
  console.error(e);
  process.exit(1);
});

